1	using System.Text;
2	using Guardrails.Core.Execution;
3	using Guardrails.Core.Model;
4	
5	namespace Guardrails.Cli.Ui;
6	
7	/// <summary>
8	/// A decorator <see cref="IRunObserver"/> that keeps a plan's <c>diagram.html</c> reflecting the
9	/// run's live progress (issue #219), mirroring <see cref="OnTheFlyLogSiteObserver"/>'s shape. It
10	/// WRAPS the real observer, forwards every event verbatim, and after certain events re-renders the
11	/// diagram from an in-memory per-node status map via <see cref="HtmlDiagramRenderer.Render"/>'s
12	/// optional <c>nodeStatuses</c> parameter (02-implement-diagram-status-overlay-renderer):
13	/// <list type="bullet">
14	///   <item>On <see cref="TaskStarting"/> the task's CONTAINER node flips to <c>"running"</c>
15	///     (coarse — per-check granularity for a task's own checks is unnecessary here since they have
16	///     not run yet; it is driven by <see cref="GuardrailFinished"/> instead).</item>
17	///   <item>On <see cref="GuardrailFinished"/> only the SPECIFIC preflight/guardrail leaf node that
18	///     just finished flips to <c>"passed"</c>/<c>"failed"</c> — never the whole task container.</item>
19	///   <item>On <see cref="TaskFinished"/> the task's container flips to its settled status
20	///     (<c>"passed"</c>/<c>"failed"</c>/<c>"needs-human"</c>, mapped from <see cref="TaskOutcome"/>).</item>
21	/// </list>
22	///
23	/// <para>
24	/// <b>Design choice (this task's either/or):</b> the Mermaid source, its source hash, and the
25	/// task-folder-targets map are threaded straight through the constructor — the same values the
26	/// caller (mirroring <c>GraphCommand</c>'s <c>MermaidRenderer.RenderInteractive</c> /
27	/// <c>TaskFolderTargets</c> calls) already computes from the live <c>PlanDefinition</c> — rather
28	/// than re-parsing them back out of the already-written <c>diagram.html</c>'s embedded
29	/// <c>&lt;script&gt;</c> tags. Threading is simpler and avoids a fragile round-trip through HTML/JSON
30	/// that would break the moment the embedded markup's shape changes for an unrelated reason.
31	/// </para>
32	///
33	/// <para>
34	/// <b>Node-id scheme.</b> <see cref="MermaidRenderer"/>'s injective task-id → node-id-base
35	/// allocation (collision-safe sanitize + <c>_2</c>/<c>_3</c>… disambiguation) is <c>private</c>, so
36	/// this class reproduces it character-for-character (see <see cref="AllocateNodeIdBases"/> /
37	/// <see cref="Sanitize"/>) to compute the SAME container id (<c>task_&lt;base&gt;</c>) and leaf ids
38	/// (<c>task_&lt;base&gt;_pf_&lt;n&gt;</c> / <c>task_&lt;base&gt;_gr_&lt;n&gt;</c>, <c>n</c> = the
39	/// check's ordinal position when its task's <see cref="TaskNode.Preflights"/>/
40	/// <see cref="TaskNode.Guardrails"/> are sorted ordinal by <see cref="GuardrailDefinition.Name"/>,
41	/// exactly as <c>MermaidRenderer.AppendCheckNodes</c> emits them) that <c>diagram.html</c> already
42	/// embeds, so a status badge lands on the right SVG node.
43	/// </para>
44	///
45	/// <para>
46	/// This decorator's own status map is the only shared mutable state, and M4 worker threads may call
47	/// in concurrently, so all access to it — and the write that projects from it — is serialised under
48	/// one lock, mirroring <see cref="OnTheFlyLogSiteObserver"/>. Renders are best-effort: a render
49	/// failure (e.g. a transient file lock, or a bad output path) is swallowed so a UX nicety never
50	/// flips a task's outcome or aborts the run.
51	/// </para>
52	///
53	/// <para>
54	/// <b>MINIMAL STUB (this task authors failing tests only).</b> <see cref="WriteDiagram"/> always
55	/// throws <see cref="NotImplementedException"/> — the real re-render (calling
56	/// <see cref="HtmlDiagramRenderer.Render"/> and writing it to <c>diagram.html</c>) is
57	/// <c>04-implement-diagram-observer</c>'s job. Every status-map/node-id bookkeeping method above is
58	/// real (not stubbed) so the authored tests encode the CORRECT expected node ids/statuses and turn
59	/// green the moment <see cref="WriteDiagram"/> is implemented for real.
60	/// </para>
61	/// </summary>
62	public sealed class OnTheFlyDiagramObserver : IRunObserver
63	{
64	    private readonly IRunObserver _inner;
65	    private readonly string _diagramHtmlPath;
66	    private readonly string _mermaidSource;
67	    private readonly string _sourceHash;
68	    private readonly IReadOnlyDictionary<string, string> _taskFolderTargets;
69	
70	    private readonly IReadOnlyDictionary<string, TaskNode> _tasksById;
71	    private readonly IReadOnlyDictionary<string, string> _nodeIdBaseByTaskId;
72	
73	    // Per-node status word (container + leaf check ids). Mutated and projected under one lock —
74	    // events may arrive from concurrent M4 workers, and the render reads the whole map, so the two
75	    // must not race (mirrors OnTheFlyLogSiteObserver's _gate).
76	    private readonly object _gate = new();
77	    private readonly Dictionary<string, string> _statusByNode = new(StringComparer.Ordinal);
78	
79	    /// <param name="inner">The real observer every event is forwarded to (live or console).</param>
80	    /// <param name="tasks">The plan's tasks — used to resolve container/leaf node ids.</param>
81	    /// <param name="diagramHtmlPath">The plan's <c>diagram.html</c> path, re-rendered in place.</param>
82	    /// <param name="mermaidSource">
83	    /// The interactive Mermaid source (<c>MermaidRenderer.RenderInteractive</c>'s output) to re-embed
84	    /// on every re-render — identical to what <c>diagram.html</c> already carries.
85	    /// </param>
86	    /// <param name="sourceHash">The plan's <c>source-sha256</c> provenance stamp.</param>
87	    /// <param name="taskFolderTargets">
88	    /// The task-container-id → plan-relative-folder-path map (<c>MermaidRenderer.TaskFolderTargets</c>)
89	    /// the title-band click overlay needs, re-embedded unchanged on every re-render.
90	    /// </param>
91	    public OnTheFlyDiagramObserver(
92	        IRunObserver inner,
93	        IReadOnlyList<TaskNode> tasks,
94	        string diagramHtmlPath,
95	        string mermaidSource,
96	        string sourceHash,
97	        IReadOnlyDictionary<string, string> taskFolderTargets)
98	    {
99	        _inner = inner ?? throw new ArgumentNullException(nameof(inner));
100	        ArgumentNullException.ThrowIfNull(tasks);
101	        _diagramHtmlPath = diagramHtmlPath ?? throw new ArgumentNullException(nameof(diagramHtmlPath));
102	        _mermaidSource = mermaidSource ?? throw new ArgumentNullException(nameof(mermaidSource));
103	        _sourceHash = sourceHash ?? throw new ArgumentNullException(nameof(sourceHash));
104	        _taskFolderTargets = taskFolderTargets ?? throw new ArgumentNullException(nameof(taskFolderTargets));
105	
106	        _tasksById = tasks.ToDictionary(t => t.Id, StringComparer.Ordinal);
107	        _nodeIdBaseByTaskId = AllocateNodeIdBases(tasks);
108	    }
109	
110	    public void TaskStarting(TaskNode task)
111	    {
112	        _inner.TaskStarting(task);
113	        SetStatus(ContainerId(task), "running");
114	        Render();
115	    }
116	
117	    public void AttemptStarting(TaskNode task, int attempt, int budget) =>
118	        _inner.AttemptStarting(task, attempt, budget);
119	
120	    public void GuardrailFinished(TaskNode task, GuardrailResult result)
121	    {
122	        _inner.GuardrailFinished(task, result);
123	
124	        string? nodeId = ResolveCheckNodeId(task, result.Name);
125	        if (nodeId is not null)
126	        {
127	            SetStatus(nodeId, result.Passed ? "passed" : "failed");
128	        }
129	
130	        Render();
131	    }
132	
133	    public void TaskFinished(TaskResult result)
134	    {
135	        _inner.TaskFinished(result);
136	
137	        if (_tasksById.TryGetValue(result.TaskId, out TaskNode? task))
138	        {
139	            SetStatus(ContainerId(task), SettledStatusWord(result.Outcome));
140	        }
141	
142	        Render();
143	    }
144	
145	    public void PlanHashMismatch(string previousPlanHash) => _inner.PlanHashMismatch(previousPlanHash);
146	
147	    public void ParallelismClampedNoProvider(int requested) => _inner.ParallelismClampedNoProvider(requested);
148	
149	    public void CleanupFailed(string owner, Exception error) => _inner.CleanupFailed(owner, error);
150	
151	    public void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) =>
152	        _inner.PromptPaused(task, reason, backoff, pauseCount);
153	
154	    // --- status-map bookkeeping -------------------------------------------------------------
155	
156	    private void SetStatus(string nodeId, string status)
157	    {
158	        lock (_gate)
159	        {
160	            _statusByNode[nodeId] = status;
161	        }
162	    }
163	
164	    /// <summary>
165	    /// Rewrite <c>diagram.html</c> from the current status map. Holds the lock for the whole render
166	    /// so the status snapshot is internally consistent. Best-effort via <see cref="TryRender"/>.
167	    /// </summary>
168	    private void Render()
169	    {
170	        lock (_gate)
171	        {
172	            var snapshot = new Dictionary<string, string>(_statusByNode, StringComparer.Ordinal);
173	            TryRender(() => WriteDiagram(snapshot));
174	        }
175	    }
176	
177	    /// <summary>
178	    /// MINIMAL STUB (issue #219 wiring): the real re-render — call
179	    /// <see cref="HtmlDiagramRenderer.Render"/> with <paramref name="nodeStatuses"/> and atomically
180	    /// write the result to <see cref="_diagramHtmlPath"/> — is <c>04-implement-diagram-observer</c>'s
181	    /// job. Deliberately throws so every render-triggering test authored against this class is a
182	    /// TDD red until that task lands. References every constructor-only field so none is flagged
183	    /// unused under this repo's TreatWarningsAsErrors policy.
184	    /// </summary>
185	    private void WriteDiagram(IReadOnlyDictionary<string, string> nodeStatuses)
186	    {
187	        throw new NotImplementedException(
188	            "OnTheFlyDiagramObserver.WriteDiagram is a stub (04-implement-diagram-observer): "
189	            + $"path={_diagramHtmlPath}, sourceHash={_sourceHash}, "
190	            + $"mermaidSourceLength={_mermaidSource.Length}, "
191	            + $"taskFolderTargetsCount={_taskFolderTargets.Count}, "
192	            + $"nodeStatusesCount={nodeStatuses.Count}.");
193	    }
194	
195	    /// <summary>
196	    /// Run a render action, swallowing IO failures: the on-the-fly diagram is a UX nicety and must
197	    /// never flip a task's outcome or abort the run. A transient lock/torn-read is retried by the
198	    /// next event. Mirrors <see cref="OnTheFlyLogSiteObserver"/>'s identical helper exactly.
199	    /// </summary>
200	    private static void TryRender(Action render)
201	    {
202	        try
203	        {
204	            render();
205	        }
206	        catch (IOException)
207	        {
208	            // best-effort — the next event re-renders
209	        }
210	        catch (UnauthorizedAccessException)
211	        {
212	            // best-effort — never let a diagram-path permission hiccup abort the run
213	        }
214	    }
215	
216	    // --- node-id resolution -------------------------------------------------------------------
217	
218	    private string ContainerId(TaskNode task) => $"task_{_nodeIdBaseByTaskId[task.Id]}";
219	
220	    /// <summary>
221	    /// Resolve a finished check's specific leaf node id: <paramref name="checkName"/> is looked up
222	    /// first against <paramref name="task"/>'s <see cref="TaskNode.Preflights"/>, then its
223	    /// <see cref="TaskNode.Guardrails"/> (both sorted ordinal by name, mirroring
224	    /// <c>MermaidRenderer.AppendCheckNodes</c>'s emission order) — so a task-level preflight and a
225	    /// guardrail are never confused even if their names happened to collide. Returns null
226	    /// (defensive — never set a status for an unrecognized check) when no check matches.
227	    /// </summary>
228	    private string? ResolveCheckNodeId(TaskNode task, string checkName)
229	    {
230	        string @base = _nodeIdBaseByTaskId[task.Id];
231	
232	        int pfIndex = IndexOfByName(task.Preflights, checkName);
233	        if (pfIndex >= 0)
234	        {
235	            return $"task_{@base}_pf_{pfIndex}";
236	        }
237	
238	        int grIndex = IndexOfByName(task.Guardrails, checkName);
239	        return grIndex >= 0 ? $"task_{@base}_gr_{grIndex}" : null;
240	    }
241	
242	    private static int IndexOfByName(IReadOnlyList<GuardrailDefinition> checks, string name)
243	    {
244	        List<GuardrailDefinition> sorted = checks.OrderBy(c => c.Name, StringComparer.Ordinal).ToList();
245	        for (int i = 0; i < sorted.Count; i++)
246	        {
247	            if (string.Equals(sorted[i].Name, name, StringComparison.Ordinal))
248	            {
249	                return i;
250	            }
251	        }
252	
253	        return -1;
254	    }
255	
256	    /// <summary>
257	    /// Map a finished task's outcome to one of the diagram's three settled status words — the
258	    /// live/pending words ("running"/"pending") never apply here since the task has already
259	    /// finished. <see cref="TaskOutcome.Succeeded"/>/<see cref="TaskOutcome.Skipped"/> (resume found
260	    /// it already succeeded) both read as "passed"; <see cref="TaskOutcome.NeedsHuman"/>/
261	    /// <see cref="TaskOutcome.RateLimited"/>/<see cref="TaskOutcome.Cancelled"/> (an ambiguous,
262	    /// operator-actionable halt) all read as "needs-human"; everything else — a genuine action or
263	    /// guardrail failure, an invalid fragment, or a blocked dependency — reads as "failed".
264	    /// <see cref="TaskOutcome.TransientPause"/> never reaches here (never reported to
265	    /// <see cref="TaskFinished"/> — see its own doc comment).
266	    /// </summary>
267	    private static string SettledStatusWord(TaskOutcome outcome) => outcome switch
268	    {
269	        TaskOutcome.Succeeded => "passed",
270	        TaskOutcome.Skipped => "passed",
271	        TaskOutcome.NeedsHuman => "needs-human",
272	        TaskOutcome.RateLimited => "needs-human",
273	        TaskOutcome.Cancelled => "needs-human",
274	        _ => "failed", // ActionFailed, GuardrailFailed, InvalidFragment, Blocked
275	    };
276	
277	    // --- replicated from MermaidRenderer (private there) — see class remarks, "Node-id scheme" ---
278	
279	    private static IReadOnlyDictionary<string, string> AllocateNodeIdBases(IReadOnlyList<TaskNode> tasks)
280	    {
281	        List<TaskNode> ordered = tasks.OrderBy(t => t.Id, StringComparer.Ordinal).ToList();
282	        var bases = new Dictionary<string, string>(StringComparer.Ordinal);
283	        var taken = new HashSet<string>(StringComparer.Ordinal);
284	
285	        foreach (TaskNode task in ordered)
286	        {
287	            string candidate = Sanitize(task.Id);
288	            if (!taken.Add(candidate))
289	            {
290	                int suffix = 2;
291	                string disambiguated;
292	                do
293	                {
294	                    disambiguated = $"{candidate}_{suffix}";
295	                    suffix++;
296	                }
297	                while (!taken.Add(disambiguated));
298	
299	                candidate = disambiguated;
300	            }
301	
302	            bases[task.Id] = candidate;
303	        }
304	
305	        return bases;
306	    }
307	
308	    private static string Sanitize(string id)
309	    {
310	        var sb = new StringBuilder(id.Length);
311	        foreach (char c in id)
312	        {
313	            bool safe = c is (>= 'a' and <= 'z') or (>= 'A' and <= 'Z') or (>= '0' and <= '9');
314	            sb.Append(safe ? c : '_');
315	        }
316	
317	        return sb.ToString();
318	    }
319	}
