using Guardrails.Core.Model;

namespace Guardrails.Integration.Tests;

/// <summary>
/// Exercises the on-the-fly diagram decorator (<see cref="OnTheFlyDiagramObserver"/>, issue #219):
/// as tasks/checks progress it re-renders <c>diagram.html</c> with the right per-node status
/// (container-level on <c>TaskStarting</c>/<c>TaskFinished</c>, specific-leaf-level on
/// <c>GuardrailFinished</c>), and forwards EVERY event to the inner observer. Driven directly
/// against the decorator with hand-built fixtures (no real Scheduler), asserting on the rendered
/// <c>diagram.html</c> FILE CONTENTS.
/// <para>
/// <b>MINIMAL STUB, deliberate TDD red.</b> <see cref="OnTheFlyDiagramObserver"/>'s actual re-render
/// (<c>WriteDiagram</c>) always throws <see cref="NotImplementedException"/> today — every test here
/// that triggers a render (all but <see cref="EveryOtherObserverEvent_IsForwardedToInner_Unchanged"/>)
/// is RED against that stub and turns GREEN once <c>04-implement-diagram-observer</c> lands the real
/// implementation. Every path used below is rooted under a fresh OS temp directory (never a bare
/// relative literal), so a stub or real render can never write outside this test's own throwaway
/// tree — see <see cref="TempSite"/>.
/// </para>
/// </summary>
public sealed class OnTheFlyDiagramObserverTests
{
    // === status-map/node-id correctness (RED against the throwing stub) =====================

    [Fact]
    public void TaskStarting_RerendersDiagramWithTheTaskMarkedRunning()
    {
        using var temp = new TempSite();
        TaskNode task = temp.Task("01-root");
        var observer = temp.Observer(IRunObserver.Null, [task]);

        observer.TaskStarting(task);

        string html = temp.ReadDiagram();
        Assert.Contains("\"task_01_root\":\"running\"", html, StringComparison.Ordinal);
    }

    [Fact]
    public void GuardrailFinished_RerendersDiagramWithThatChecksSettledStatus()
    {
        using var temp = new TempSite();
        TaskNode task = temp.Task("01-root", guardrailNames: ["01-alpha", "02-beta"]);
        var observer = temp.Observer(IRunObserver.Null, [task]);

        observer.TaskStarting(task);
        observer.GuardrailFinished(task, new GuardrailResult { Name = "01-alpha", Passed = true });

        string afterFirst = temp.ReadDiagram();
        // Only the check that finished flips — the container (still running) and the OTHER,
        // not-yet-finished check must be unaffected by this specific event.
        Assert.Contains("\"task_01_root_gr_0\":\"passed\"", afterFirst, StringComparison.Ordinal);
        Assert.Contains("\"task_01_root\":\"running\"", afterFirst, StringComparison.Ordinal);
        Assert.DoesNotContain("task_01_root_gr_1", afterFirst, StringComparison.Ordinal);

        observer.GuardrailFinished(task, new GuardrailResult { Name = "02-beta", Passed = false });

        string afterSecond = temp.ReadDiagram();
        // The second check's OWN failure must not retroactively touch the first check's status.
        Assert.Contains("\"task_01_root_gr_0\":\"passed\"", afterSecond, StringComparison.Ordinal);
        Assert.Contains("\"task_01_root_gr_1\":\"failed\"", afterSecond, StringComparison.Ordinal);
    }

    [Theory]
    [InlineData(TaskOutcome.Succeeded, "passed")]
    [InlineData(TaskOutcome.GuardrailFailed, "failed")]
    [InlineData(TaskOutcome.NeedsHuman, "needs-human")]
    public void TaskFinished_RerendersDiagramWithTheTasksSettledStatus(TaskOutcome outcome, string expectedStatus)
    {
        using var temp = new TempSite();
        TaskNode task = temp.Task("01-root");
        var observer = temp.Observer(IRunObserver.Null, [task]);

        observer.TaskStarting(task);
        observer.TaskFinished(new TaskResult { TaskId = task.Id, Outcome = outcome, Summary = "done" });

        string html = temp.ReadDiagram();
        Assert.Contains($"\"task_01_root\":\"{expectedStatus}\"", html, StringComparison.Ordinal);
    }

    // === pass-through (the one test expected to PASS against the stub) ======================

    [Fact]
    public void EveryOtherObserverEvent_IsForwardedToInner_Unchanged()
    {
        using var temp = new TempSite();
        TaskNode task = temp.Task("01-root");
        var inner = new RecordingObserver();
        var observer = temp.Observer(inner, [task]);

        observer.AttemptStarting(task, attempt: 2, budget: 3);
        observer.PlanHashMismatch("sha256:previous");
        observer.ParallelismClampedNoProvider(requested: 4);
        var cleanupError = new InvalidOperationException("cleanup boom");
        observer.CleanupFailed("(prune-orphans)", cleanupError);
        observer.PromptPaused(task, "rate limited", TimeSpan.FromSeconds(30), pauseCount: 1);

        Assert.Equal(
            new[]
            {
                "AttemptStarting:01-root:2:3",
                "PlanHashMismatch:sha256:previous",
                "ParallelismClampedNoProvider:4",
                "CleanupFailed:(prune-orphans):cleanup boom",
                "PromptPaused:01-root:rate limited:30:1",
            },
            inner.Events);
    }

    // === best-effort render failure (RED against the throwing stub) =========================

    [Fact]
    public void ARenderFailure_IsSwallowed_AndDoesNotThrow()
    {
        using var temp = new TempSite();
        TaskNode task = temp.Task("01-root");

        // A path whose PARENT segment is itself an existing plain FILE (not a directory) is
        // guaranteed to fail any real write with an IOException (DirectoryNotFoundException is an
        // IOException subtype) — entirely inside this test's own OS-temp tree, never touching the
        // repo working directory regardless of the test runner's current directory.
        string blockerFile = Path.Combine(temp.Dir, "blocker-file");
        File.WriteAllText(blockerFile, "not a directory");
        string invalidDiagramPath = Path.Combine(blockerFile, "diagram.html");

        var observer = new OnTheFlyDiagramObserver(
            IRunObserver.Null, [task], invalidDiagramPath, temp.MermaidSource, temp.SourceHash, temp.TaskFolderTargets);

        Exception? thrown = Record.Exception(() => observer.TaskStarting(task));

        Assert.Null(thrown);
    }

    // === fixtures =============================================================================

    /// <summary>Records the identity + key args of every forwarded event so the pass-through is provable.</summary>
    private sealed class RecordingObserver : IRunObserver
    {
        public List<string> Events { get; } = [];

        public void TaskStarting(TaskNode task) => Events.Add($"TaskStarting:{task.Id}");

        public void AttemptStarting(TaskNode task, int attempt, int budget) =>
            Events.Add($"AttemptStarting:{task.Id}:{attempt}:{budget}");

        public void TaskFinished(TaskResult result) => Events.Add($"TaskFinished:{result.TaskId}");

        public void GuardrailFinished(TaskNode task, GuardrailResult result) =>
            Events.Add($"GuardrailFinished:{task.Id}:{result.Name}");

        public void PlanHashMismatch(string previousPlanHash) =>
            Events.Add($"PlanHashMismatch:{previousPlanHash}");

        public void ParallelismClampedNoProvider(int requested) =>
            Events.Add($"ParallelismClampedNoProvider:{requested}");

        public void CleanupFailed(string owner, Exception error) =>
            Events.Add($"CleanupFailed:{owner}:{error.Message}");

        public void PromptPaused(TaskNode task, string reason, TimeSpan backoff, int pauseCount) =>
            Events.Add($"PromptPaused:{task.Id}:{reason}:{(int)backoff.TotalSeconds}:{pauseCount}");
    }

    /// <summary>A throwaway plan-shaped directory tree, entirely under the OS temp root, with
    /// helpers to build fixtures and construct the observer/read its output — mirrors
    /// <c>OnTheFlyLogSiteTests.TempSite</c>. Every path this class hands out is rooted under
    /// <see cref="Dir"/>, so no test in this file can ever write outside its own throwaway tree.</summary>
    private sealed class TempSite : IDisposable
    {
        public string Dir { get; } = Path.Combine(Path.GetTempPath(), "gr-otf-diagram-" + Guid.NewGuid().ToString("N"));

        public string DiagramHtmlPath => Path.Combine(Dir, "diagram.html");

        public string MermaidSource { get; } = "flowchart TD\n  task_01_root[\"01-root\"]\n";

        public string SourceHash { get; } = "deadbeef";

        public IReadOnlyDictionary<string, string> TaskFolderTargets { get; } =
            new Dictionary<string, string>(StringComparer.Ordinal) { ["task_01_root"] = "tasks/01-root/" };

        public TempSite() => Directory.CreateDirectory(Dir);

        public TaskNode Task(string id, IReadOnlyList<string>? guardrailNames = null)
        {
            IReadOnlyList<string> names = guardrailNames ?? ["01-check"];
            return new TaskNode
            {
                Id = id,
                Directory = Path.Combine(Dir, "tasks", id),
                Description = "task " + id,
                Action = new ActionDefinition { Path = "action.ps1", Kind = ActionKind.Script },
                Guardrails = names
                    .Select(n => new GuardrailDefinition { Name = n, Path = $"{n}.ps1", Kind = ActionKind.Script })
                    .ToList(),
            };
        }

        public OnTheFlyDiagramObserver Observer(IRunObserver inner, IReadOnlyList<TaskNode> tasks) =>
            new(inner, tasks, DiagramHtmlPath, MermaidSource, SourceHash, TaskFolderTargets);

        public string ReadDiagram() => File.ReadAllText(DiagramHtmlPath);

        public void Dispose()
        {
            try { Directory.Delete(Dir, recursive: true); } catch (Exception) { /* best effort */ }
        }
    }
}

