1	using Guardrails.Core.Execution;
2	using Guardrails.Core.Model;
3	
4	namespace Guardrails.Cli.Ui;
5	
6	/// <summary>
7	/// A decorator <see cref="IRunObserver"/> that keeps the DURING-RUN static log site
8	/// (<c>logs/&lt;runId&gt;/index.html</c> + per-task pages) up to date as the run proceeds (issue #141
9	/// item 2). It WRAPS the real observer (live <see cref="LiveRunObserver"/> or
10	/// <see cref="ConsoleRunObserver"/>), forwards every event verbatim, and AFTER forwarding rewrites
11	/// the site through <see cref="LogSiteRenderer"/>:
12	/// <list type="bullet">
13	///   <item>On <see cref="TaskStarting"/> a task flips pending → running and the index is rewritten —
14	///     a running task links to the LIVE server (a click tails it) when a server is up, else plain text.</item>
15	///   <item>On <see cref="TaskFinished"/> a task flips to its settled status, its static page is written
16	///     (<see cref="LogSiteRenderer.WriteTaskPageIfHasAttempts"/>), and the index is rewritten — a
17	///     settled task with attempts on disk now links to its static page.</item>
18	/// </list>
19	///
20	/// <para>The index always carries the <c>meta refresh</c> (<c>includeRefresh:true</c>) so a
21	/// <c>file://</c> view re-reads it as it is rewritten; the DURABLE final/<c>--export</c> index (no
22	/// refresh, all-static) is written separately by the run's end-of-run path, NOT here.</para>
23	///
24	/// <para>The renderer writes atomically, so a browser never reads a torn file. This decorator's own
25	/// status map is the only shared mutable state, and M4 worker threads call in concurrently, so all
26	/// access to it — and the write that projects from it — is serialised under one lock. Renders are
27	/// best-effort: a render failure (e.g. a transient file lock) is swallowed so a UX nicety never
28	/// flips a task's outcome or aborts the run.</para>
29	/// </summary>
30	public sealed class OnTheFlyLogSiteObserver : IRunObserver
