/// </summary>
private void Render()
{
    lock (_gate)
    {
        var snapshot = new Dictionary<string, string>(_statusByNode, StringComparer.Ordinal);
        TryRender(() => WriteDiagram(snapshot));
    }
}

/// <summary>
/// Re-render <c>diagram.html</c> (issue #219 wiring) from <paramref name="nodeStatuses"/> via
/// <see cref="HtmlDiagramRenderer.Render"/> and write it atomically to
/// <see cref="_diagramHtmlPath"/>. <c>includeRefresh: true</c> — this is always the DURING-RUN
/// diagram; the final, no-refresh settled render is a separate end-of-run concern
/// (<c>06-wire-diagramobserver-into-runcommand</c>), not this decorator's job.
/// </summary>
private void WriteDiagram(IReadOnlyDictionary<string, string> nodeStatuses)
{
    string html = HtmlDiagramRenderer.Render(
        _mermaidSource, _sourceHash, _taskFolderTargets, nodeStatuses: nodeStatuses, includeRefresh: true);
    AtomicFile.WriteAllText(_diagramHtmlPath, html);
}

